//! Command-line handling mirroring the original C++ `main`.
//!
//! The C++ program reads `--a <count>` with `std::stoi` and lets any failure
//! escape `main`, so a bad argument kills the process through
//! `std::terminate`. The helpers below reproduce that behaviour exactly,
//! including the message libstdc++ prints and the `SIGABRT` exit status.

use std::process;

/// Number of entries inserted when `--a` is not given.
pub const DEFAULT_COUNT: i32 = 1;

/// Largest magnitude that still needs precise range checking; anything above it
/// is out of `int` range whatever the sign, so accumulation can stop there.
const MAGNITUDE_GUARD: i64 = i32::MAX as i64 + 1;

/// Resolves the entry count from `argv`, which must include the program name.
///
/// Matches `if (argc > 1 && std::string(argv[1]) == "--a") count = stoi(argv[2])`:
/// a leading argument other than `--a` is ignored, and any argument after the
/// count is ignored as well.
pub fn parse_count(args: &[String]) -> i32 {
    if args.len() > 1 && args[1] == "--a" {
        match args.get(2) {
            Some(value) => stoi(value),
            // `std::string(argv[2])` with argv[2] == nullptr.
            None => terminate("std::logic_error", "basic_string::_S_construct null not valid"),
        }
    } else {
        DEFAULT_COUNT
    }
}

/// Reimplementation of `std::stoi`.
///
/// Skips leading whitespace, accepts an optional sign, consumes base-10 digits
/// and ignores whatever follows them. Terminates the process the way the C++
/// binary does when no digits are found (`std::invalid_argument`) or the value
/// does not fit in an `int` (`std::out_of_range`).
pub fn stoi(text: &str) -> i32 {
    let bytes = text.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() && is_space(bytes[pos]) {
        pos += 1;
    }

    let negative = match bytes.get(pos) {
        Some(b'-') => {
            pos += 1;
            true
        }
        Some(b'+') => {
            pos += 1;
            false
        }
        _ => false,
    };

    let first_digit = pos;
    let mut magnitude: i64 = 0;
    let mut saturated = false;
    while pos < bytes.len() && bytes[pos].is_ascii_digit() {
        if !saturated {
            magnitude = magnitude * 10 + i64::from(bytes[pos] - b'0');
            saturated = magnitude > MAGNITUDE_GUARD;
        }
        pos += 1;
    }

    if pos == first_digit {
        terminate("std::invalid_argument", "stoi");
    }

    let value = if negative { -magnitude } else { magnitude };
    if saturated || value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
        terminate("std::out_of_range", "stoi");
    }
    value as i32
}

/// True for the bytes `std::isspace` accepts in the default "C" locale.
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Reproduces an uncaught C++ exception: the libstdc++ terminate handler's
/// message on stderr, then `SIGABRT`.
fn terminate(exception: &str, what: &str) -> ! {
    eprintln!("terminate called after throwing an instance of '{}'", exception);
    eprintln!("  what():  {}", what);
    process::abort()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn argv(args: &[&str]) -> Vec<String> {
        std::iter::once("test1")
            .chain(args.iter().copied())
            .map(str::to_string)
            .collect()
    }

    #[test]
    fn count_defaults_to_one() {
        assert_eq!(parse_count(&argv(&[])), 1);
        assert_eq!(parse_count(&argv(&["--b", "7"])), 1);
    }

    #[test]
    fn count_reads_the_a_option() {
        assert_eq!(parse_count(&argv(&["--a", "0"])), 0);
        assert_eq!(parse_count(&argv(&["--a", "5"])), 5);
        assert_eq!(parse_count(&argv(&["--a", "5", "ignored"])), 5);
    }

    #[test]
    fn stoi_matches_libstdcxx() {
        assert_eq!(stoi("007"), 7);
        assert_eq!(stoi("+4"), 4);
        assert_eq!(stoi("-3"), -3);
        assert_eq!(stoi("  42abc"), 42);
        assert_eq!(stoi("3.9"), 3);
        assert_eq!(stoi("0x10"), 0);
        assert_eq!(stoi("2147483647"), i32::MAX);
        assert_eq!(stoi("-2147483648"), i32::MIN);
    }
}

