//! Hash map based on hopscotch hashing.
//!
//! Hopscotch hashing keeps every entry within a fixed *neighborhood* of the
//! bucket its hash maps to. Each bucket carries a bitmap naming the slots in
//! its neighborhood that hold entries belonging to it, so a lookup touches one
//! cache line and only ever compares keys that hash home to the same bucket.
//! Insertions that find no free slot nearby "hop" an occupied entry forward
//! into a distant free slot, walking the free slot backwards until it lands
//! inside the neighborhood.

mod iter;
mod map;

#[cfg(test)]
mod tests;

pub use iter::{IntoIter, Iter, IterMut, Keys, Values};
pub use map::HopscotchMap;

