//! The [`HopscotchMap`] container.

use std::borrow::Borrow;
use std::collections::hash_map::DefaultHasher;
use std::fmt;
use std::hash::{BuildHasher, BuildHasherDefault, Hash, Hasher};

use super::iter::{IntoIter, Iter, IterMut, Keys, Values};

/// How far from its home bucket an entry may be stored, and the number of
/// usable bits in a neighborhood bitmap. Two bits of the `u64` go unused, which
/// keeps the value in step with the default neighborhood of the C++ container.
const NEIGHBORHOOD: usize = 62;

/// Smallest allocated bucket count. Powers of two let the home bucket be a mask
/// of the hash rather than a division.
const MIN_BUCKETS: usize = 16;

/// The table grows once it is 7/8 full. Hopscotch lookups stay flat at high load
/// factors because probing is bounded by the neighborhood.
const LOAD_NUMERATOR: usize = 7;
const LOAD_DENOMINATOR: usize = 8;

/// The default hasher, `std`'s SipHash-1-3.
type DefaultHashBuilder = BuildHasherDefault<DefaultHasher>;

pub(super) struct Bucket<K, V> {
    /// Bit `d` is set when the entry `d` slots after this one hashes home here.
    neighborhood: u64,
    pub(super) entry: Option<(K, V)>,
}

impl<K, V> Bucket<K, V> {
    fn empty() -> Self {
        Bucket {
            neighborhood: 0,
            entry: None,
        }
    }
}

/// Where a key was found.
enum Slot {
    /// Index into `buckets`.
    Bucket(usize),
    /// Index into `overflow`.
    Overflow(usize),
}

/// A hash map storing entries in the neighborhood of their home bucket.
///
/// The interface covers the parts of `tsl::hopscotch_map` the C++ tests use.
/// Note that, like the C++ container and `std::unordered_map`, [`insert`] keeps
/// the value already stored under an equal key; use [`insert_or_assign`] to
/// overwrite.
///
/// [`insert`]: HopscotchMap::insert
/// [`insert_or_assign`]: HopscotchMap::insert_or_assign
pub struct HopscotchMap<K, V, S = DefaultHashBuilder> {
    /// `bucket_count` addressable buckets followed by `NEIGHBORHOOD - 1` spare
    /// slots, so the neighborhood of the last bucket needs no wrap-around.
    buckets: Vec<Bucket<K, V>>,
    /// Entries for which no free slot could be hopped into reach. Only densely
    /// colliding keys land here, so it stays empty in practice.
    overflow: Vec<(K, V)>,
    bucket_count: usize,
    len: usize,
    hash_builder: S,
}

impl<K, V> HopscotchMap<K, V> {
    /// Creates an empty map, allocating nothing until the first insertion.
    pub fn new() -> Self {
        Self::with_hasher(DefaultHashBuilder::default())
    }

    /// Creates an empty map sized to hold `capacity` entries without growing.
    pub fn with_capacity(capacity: usize) -> Self {
        Self::with_capacity_and_hasher(capacity, DefaultHashBuilder::default())
    }
}

impl<K, V, S> HopscotchMap<K, V, S> {
    /// Creates an empty map that hashes keys with `hash_builder`.
    pub fn with_hasher(hash_builder: S) -> Self {
        HopscotchMap {
            buckets: Vec::new(),
            overflow: Vec::new(),
            bucket_count: 0,
            len: 0,
            hash_builder,
        }
    }

    /// Number of entries in the map.
    pub fn len(&self) -> usize {
        self.len
    }

    /// True when the map holds no entries.
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Entries the map can hold before it has to grow.
    pub fn capacity(&self) -> usize {
        max_load(self.bucket_count)
    }

    /// Removes every entry, keeping the allocated buckets.
    pub fn clear(&mut self) {
        for bucket in &mut self.buckets {
            bucket.neighborhood = 0;
            bucket.entry = None;
        }
        self.overflow.clear();
        self.len = 0;
    }

    /// Visits every entry in unspecified order.
    pub fn iter(&self) -> Iter<'_, K, V> {
        Iter::new(&self.buckets, &self.overflow, self.len)
    }

    /// Visits every entry in unspecified order, allowing values to be modified.
    pub fn iter_mut(&mut self) -> IterMut<'_, K, V> {
        IterMut::new(&mut self.buckets, &mut self.overflow, self.len)
    }

    /// Visits every key in unspecified order.
    pub fn keys(&self) -> Keys<'_, K, V> {
        Keys::new(self.iter())
    }

    /// Visits every value in unspecified order.
    pub fn values(&self) -> Values<'_, K, V> {
        Values::new(self.iter())
    }
}

impl<K, V, S> HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    /// Creates an empty map sized to hold `capacity` entries without growing,
    /// hashing keys with `hash_builder`.
    pub fn with_capacity_and_hasher(capacity: usize, hash_builder: S) -> Self {
        let mut map = Self::with_hasher(hash_builder);
        map.reserve(capacity);
        map
    }

    /// Grows the table so `additional` more entries fit without a rehash.
    pub fn reserve(&mut self, additional: usize) {
        let needed = self.len.saturating_add(additional);
        if needed > self.capacity() {
            self.rehash(buckets_for(needed));
        }
    }

    /// Inserts `(key, value)` unless an equal key is already present, returning
    /// whether the entry was inserted.
    pub fn insert(&mut self, (key, value): (K, V)) -> bool {
        let hash = self.hash(&key);
        if self.find(&key, hash).is_some() {
            return false;
        }
        self.reserve(1);
        self.place(key, value, hash);
        self.len += 1;
        true
    }

    /// Inserts `(key, value)`, replacing any value already stored under an equal
    /// key and returning it.
    pub fn insert_or_assign(&mut self, key: K, value: V) -> Option<V> {
        let hash = self.hash(&key);
        if let Some(slot) = self.find(&key, hash) {
            let stored = match slot {
                Slot::Bucket(index) => &mut self.buckets[index].entry.as_mut().unwrap().1,
                Slot::Overflow(index) => &mut self.overflow[index].1,
            };
            return Some(std::mem::replace(stored, value));
        }
        self.reserve(1);
        self.place(key, value, hash);
        self.len += 1;
        None
    }

    /// Borrows the value stored under `key`.
    pub fn get<Q>(&self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        match self.find(key, self.hash(key))? {
            Slot::Bucket(index) => self.buckets[index].entry.as_ref().map(|(_, value)| value),
            Slot::Overflow(index) => Some(&self.overflow[index].1),
        }
    }

    /// Mutably borrows the value stored under `key`.
    pub fn get_mut<Q>(&mut self, key: &Q) -> Option<&mut V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        match self.find(key, self.hash(key))? {
            Slot::Bucket(index) => self.buckets[index].entry.as_mut().map(|(_, value)| value),
            Slot::Overflow(index) => Some(&mut self.overflow[index].1),
        }
    }

    /// True when an equal key is stored in the map.
    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.find(key, self.hash(key)).is_some()
    }

    /// Removes the entry stored under `key`, returning its value.
    pub fn remove<Q>(&mut self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash(key);
        let (removed_key, value) = match self.find(key, hash)? {
            Slot::Bucket(index) => {
                let entry = self.buckets[index].entry.take()?;
                // Drop the slot from its home bucket's neighborhood.
                let home = (hash as usize) & self.mask();
                self.buckets[home].neighborhood &= !(1u64 << (index - home));
                entry
            }
            Slot::Overflow(index) => self.overflow.swap_remove(index),
        };
        drop(removed_key);
        self.len -= 1;
        Some(value)
    }

    fn hash<Q>(&self, key: &Q) -> u64
    where
        Q: Hash + ?Sized,
    {
        let mut hasher = self.hash_builder.build_hasher();
        key.hash(&mut hasher);
        hasher.finish()
    }

    /// Turns a hash into a home bucket index.
    fn mask(&self) -> usize {
        self.bucket_count - 1
    }

    /// Locates `key`, scanning only the neighborhood of its home bucket and, as
    /// a last resort, the overflow list.
    fn find<Q>(&self, key: &Q, hash: u64) -> Option<Slot>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if self.bucket_count == 0 {
            return None;
        }

        let home = (hash as usize) & self.mask();
        let mut neighborhood = self.buckets[home].neighborhood;
        while neighborhood != 0 {
            let distance = neighborhood.trailing_zeros() as usize;
            if let Some((stored, _)) = &self.buckets[home + distance].entry {
                if stored.borrow() == key {
                    return Some(Slot::Bucket(home + distance));
                }
            }
            neighborhood &= neighborhood - 1;
        }

        self.overflow
            .iter()
            .position(|(stored, _)| stored.borrow() == key)
            .map(Slot::Overflow)
    }

    /// Stores an entry known to be absent. Never changes `len`, so rehashing can
    /// reuse it.
    fn place(&mut self, key: K, value: V, hash: u64) {
        let home = (hash as usize) & self.mask();

        let Some(free) = (home..self.buckets.len()).find(|&i| self.buckets[i].entry.is_none())
        else {
            self.overflow.push((key, value));
            return;
        };

        // Walk the free slot back towards `home` until it is close enough to be
        // named by the home bucket's bitmap.
        let mut free = free;
        while free - home >= NEIGHBORHOOD {
            match self.hop_back(free) {
                Some(vacated) => free = vacated,
                None => {
                    self.overflow.push((key, value));
                    return;
                }
            }
        }

        self.buckets[free].entry = Some((key, value));
        self.buckets[home].neighborhood |= 1u64 << (free - home);
    }

    /// Moves some entry into the free slot at `free` and returns the slot it
    /// vacated, which is always closer to the start of the table.
    ///
    /// Returns `None` when no entry within reach of `free` may legally move
    /// there, meaning the free slot cannot be brought any closer.
    fn hop_back(&mut self, free: usize) -> Option<usize> {
        // `free >= home + NEIGHBORHOOD >= NEIGHBORHOOD`, so this cannot wrap.
        let earliest = free + 1 - NEIGHBORHOOD;
        for home in earliest..free {
            // Entries belonging to `home` that sit before `free`; any of them
            // can move to `free` and stay inside `home`'s neighborhood.
            let distance = free - home;
            let movable = self.buckets[home].neighborhood & ((1u64 << distance) - 1);
            if movable == 0 {
                continue;
            }

            let vacated = home + movable.trailing_zeros() as usize;
            self.buckets[free].entry = self.buckets[vacated].entry.take();
            self.buckets[home].neighborhood &= !(1u64 << (vacated - home));
            self.buckets[home].neighborhood |= 1u64 << distance;
            return Some(vacated);
        }
        None
    }

    /// Reallocates to `bucket_count` buckets and reinserts every entry.
    fn rehash(&mut self, bucket_count: usize) {
        let bucket_count = bucket_count.max(MIN_BUCKETS).next_power_of_two();
        let slots = bucket_count + NEIGHBORHOOD - 1;

        let old_buckets = std::mem::replace(
            &mut self.buckets,
            (0..slots).map(|_| Bucket::empty()).collect(),
        );
        let old_overflow = std::mem::take(&mut self.overflow);
        self.bucket_count = bucket_count;

        let entries = old_buckets
            .into_iter()
            .filter_map(|bucket| bucket.entry)
            .chain(old_overflow);
        for (key, value) in entries {
            let hash = self.hash(&key);
            self.place(key, value, hash);
        }
    }
}

/// Entries a table of `bucket_count` buckets holds before growing.
fn max_load(bucket_count: usize) -> usize {
    bucket_count / LOAD_DENOMINATOR * LOAD_NUMERATOR
}

/// Smallest bucket count whose load limit covers `entries`.
fn buckets_for(entries: usize) -> usize {
    let mut bucket_count = MIN_BUCKETS;
    while max_load(bucket_count) < entries {
        bucket_count *= 2;
    }
    bucket_count
}

impl<K, V> Default for HopscotchMap<K, V> {
    fn default() -> Self {
        Self::new()
    }
}

impl<K, V, S> IntoIterator for HopscotchMap<K, V, S> {
    type Item = (K, V);
    type IntoIter = IntoIter<K, V>;

    fn into_iter(self) -> Self::IntoIter {
