            self.insert_or_assign(entry.0, entry.1);
        }
    }
}

impl<K, V, S> FromIterator<(K, V)> for HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher + Default,
{
    fn from_iter<I: IntoIterator<Item = (K, V)>>(entries: I) -> Self {
        let mut map = Self::with_hasher(S::default());
