//! Iterators over a [`HopscotchMap`](super::HopscotchMap).
//!
//! Every iterator walks the bucket array first and the overflow list second, so
//! the order entries come out in is unspecified and unrelated to insertion.

use std::iter::FusedIterator;
use std::slice;
use std::vec;

use super::map::Bucket;

/// Borrowing iterator over `(&K, &V)` pairs.
pub struct Iter<'a, K, V> {
    buckets: slice::Iter<'a, Bucket<K, V>>,
    overflow: slice::Iter<'a, (K, V)>,
    remaining: usize,
}

impl<'a, K, V> Iter<'a, K, V> {
    pub(super) fn new(
        buckets: &'a [Bucket<K, V>],
        overflow: &'a [(K, V)],
        remaining: usize,
    ) -> Self {
        Iter {
            buckets: buckets.iter(),
            overflow: overflow.iter(),
            remaining,
        }
    }
}

impl<'a, K, V> Iterator for Iter<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        for bucket in self.buckets.by_ref() {
            if let Some((key, value)) = &bucket.entry {
                self.remaining -= 1;
                return Some((key, value));
            }
        }
        let (key, value) = self.overflow.next()?;
        self.remaining -= 1;
        Some((key, value))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<K, V> ExactSizeIterator for Iter<'_, K, V> {}
impl<K, V> FusedIterator for Iter<'_, K, V> {}

impl<K, V> Clone for Iter<'_, K, V> {
    fn clone(&self) -> Self {
        Iter {
            buckets: self.buckets.clone(),
            overflow: self.overflow.clone(),
            remaining: self.remaining,
        }
    }
}

/// Iterator over `(&K, &mut V)` pairs.
pub struct IterMut<'a, K, V> {
    buckets: slice::IterMut<'a, Bucket<K, V>>,
    overflow: slice::IterMut<'a, (K, V)>,
    remaining: usize,
}

impl<'a, K, V> IterMut<'a, K, V> {
    pub(super) fn new(
        buckets: &'a mut [Bucket<K, V>],
        overflow: &'a mut [(K, V)],
        remaining: usize,
    ) -> Self {
        IterMut {
            buckets: buckets.iter_mut(),
            overflow: overflow.iter_mut(),
            remaining,
        }
    }
}

impl<'a, K, V> Iterator for IterMut<'a, K, V> {
    type Item = (&'a K, &'a mut V);

    fn next(&mut self) -> Option<Self::Item> {
        for bucket in self.buckets.by_ref() {
            if let Some((key, value)) = &mut bucket.entry {
                self.remaining -= 1;
                return Some((key, value));
            }
        }
        let (key, value) = self.overflow.next()?;
        self.remaining -= 1;
        Some((key, value))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<K, V> ExactSizeIterator for IterMut<'_, K, V> {}
impl<K, V> FusedIterator for IterMut<'_, K, V> {}

/// Owning iterator over `(K, V)` pairs.
pub struct IntoIter<K, V> {
    buckets: vec::IntoIter<Bucket<K, V>>,
    overflow: vec::IntoIter<(K, V)>,
    remaining: usize,
}

impl<K, V> IntoIter<K, V> {
    pub(super) fn new(
        buckets: Vec<Bucket<K, V>>,
        overflow: Vec<(K, V)>,
        remaining: usize,
    ) -> Self {
        IntoIter {
            buckets: buckets.into_iter(),
            overflow: overflow.into_iter(),
            remaining,
        }
    }
}

impl<K, V> Iterator for IntoIter<K, V> {
    type Item = (K, V);

    fn next(&mut self) -> Option<Self::Item> {
        for bucket in self.buckets.by_ref() {
            if let Some(entry) = bucket.entry {
                self.remaining -= 1;
                return Some(entry);
            }
        }
        let entry = self.overflow.next()?;
        self.remaining -= 1;
        Some(entry)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<K, V> ExactSizeIterator for IntoIter<K, V> {}
impl<K, V> FusedIterator for IntoIter<K, V> {}

/// Iterator over the map's keys.
#[derive(Clone)]
pub struct Keys<'a, K, V> {
    inner: Iter<'a, K, V>,
}

impl<'a, K, V> Keys<'a, K, V> {
    pub(super) fn new(inner: Iter<'a, K, V>) -> Self {
        Keys { inner }
    }
}

impl<'a, K, V> Iterator for Keys<'a, K, V> {
