//! Behavioural tests for [`HopscotchMap`].

use std::hash::{BuildHasher, Hasher};

use super::HopscotchMap;

/// Hasher that folds every key into `buckets` distinct hashes, forcing the
/// clustering that drives neighborhood displacement and the overflow list.
#[derive(Clone, Copy)]
struct Clustered {
    buckets: u64,
}

struct ClusteredHasher {
    buckets: u64,
    state: u64,
}

impl BuildHasher for Clustered {
    type Hasher = ClusteredHasher;

    fn build_hasher(&self) -> Self::Hasher {
        ClusteredHasher {
            buckets: self.buckets,
            state: 0,
        }
    }
}

impl Hasher for ClusteredHasher {
    fn write(&mut self, bytes: &[u8]) {
        for &byte in bytes {
            self.state = self.state.wrapping_mul(31).wrapping_add(u64::from(byte));
        }
    }

    fn finish(&self) -> u64 {
        self.state % self.buckets
    }
}

#[test]
fn empty_map_has_no_entries() {
    let map: HopscotchMap<i32, String> = HopscotchMap::new();
    assert_eq!(map.len(), 0);
    assert!(map.is_empty());
    assert_eq!(map.get(&0), None);
    assert_eq!(map.iter().count(), 0);
}

#[test]
fn insert_reports_and_keeps_first_value() {
    let mut map: HopscotchMap<i32, String> = HopscotchMap::new();

    assert!(map.insert((1, "first".to_string())));
    assert!(!map.insert((1, "second".to_string())));

    assert_eq!(map.len(), 1);
    assert_eq!(map.get(&1).map(String::as_str), Some("first"));
}

#[test]
fn insert_or_assign_overwrites() {
    let mut map: HopscotchMap<i32, String> = HopscotchMap::new();

    assert_eq!(map.insert_or_assign(1, "first".to_string()), None);
    assert_eq!(
        map.insert_or_assign(1, "second".to_string()),
        Some("first".to_string())
    );

    assert_eq!(map.len(), 1);
    assert_eq!(map.get(&1).map(String::as_str), Some("second"));
}

#[test]
fn growing_preserves_every_entry() {
    let mut map: HopscotchMap<i32, String> = HopscotchMap::new();
    for i in 0..10_000 {
        assert!(map.insert((i, format!("value{}", i))));
    }

    assert_eq!(map.len(), 10_000);
    for i in 0..10_000 {
        assert_eq!(map.get(&i).map(String::as_str), Some(&*format!("value{}", i)));
    }
    assert_eq!(map.get(&10_000), None);
    assert!(!map.contains_key(&-1));
}

#[test]
fn removal_frees_the_slot_for_reuse() {
    let mut map: HopscotchMap<i32, String> = HopscotchMap::new();
    for i in 0..500 {
        map.insert((i, format!("value{}", i)));
    }

    for i in (0..500).step_by(2) {
        assert_eq!(map.remove(&i), Some(format!("value{}", i)));
    }
    assert_eq!(map.len(), 250);
    assert_eq!(map.remove(&0), None);

    for i in (0..500).step_by(2) {
        assert!(map.insert((i, format!("again{}", i))));
    }
    assert_eq!(map.len(), 500);
    assert_eq!(map.get(&0).map(String::as_str), Some("again0"));
    assert_eq!(map.get(&1).map(String::as_str), Some("value1"));
}

#[test]
fn displacement_handles_a_crowded_neighborhood() {
    // Eight home buckets for 4000 keys: most insertions have to hop an entry
    // out of the way, and the rest end up in the overflow list.
    let mut map = HopscotchMap::with_hasher(Clustered { buckets: 8 });
    for i in 0..4000 {
        assert!(map.insert((i, i * 2)));
    }

    assert_eq!(map.len(), 4000);
    for i in 0..4000 {
        assert_eq!(map.get(&i), Some(&(i * 2)));
    }

    for i in 0..4000 {
        assert_eq!(map.remove(&i), Some(i * 2));
    }
    assert!(map.is_empty());
}

#[test]
fn every_key_hashing_alike_still_round_trips() {
    let mut map = HopscotchMap::with_hasher(Clustered { buckets: 1 });
    for i in 0..300 {
        assert!(map.insert((i, i)));
    }
    assert!(!map.insert((7, 99)));

    assert_eq!(map.len(), 300);
    for i in 0..300 {
        assert_eq!(map.get(&i), Some(&i));
    }
}

#[test]
fn iteration_visits_each_entry_once() {
    let mut map: HopscotchMap<i32, i32> = (0..1000).map(|i| (i, i * i)).collect();

    let mut seen: Vec<(i32, i32)> = map.iter().map(|(&k, &v)| (k, v)).collect();
    seen.sort_unstable();
    assert_eq!(seen, (0..1000).map(|i| (i, i * i)).collect::<Vec<_>>());

    assert_eq!(map.iter().len(), 1000);
    assert_eq!(map.keys().count(), 1000);
    assert_eq!(map.values().count(), 1000);

    for (_, value) in map.iter_mut() {
        *value = 0;
    }
    assert!(map.values().all(|&value| value == 0));

    let mut owned: Vec<i32> = map.into_iter().map(|(key, _)| key).collect();
    owned.sort_unstable();
    assert_eq!(owned, (0..1000).collect::<Vec<_>>());
}

#[test]
fn borrowed_keys_can_be_looked_up() {
    let mut map: HopscotchMap<String, i32> = HopscotchMap::new();
    map.insert(("key".to_string(), 1));

    assert_eq!(map.get("key"), Some(&1));
    assert!(map.contains_key("key"));
    *map.get_mut("key").unwrap() = 2;
    assert_eq!(map.remove("key"), Some(2));
}

#[test]
fn clear_empties_but_keeps_capacity() {
    let mut map: HopscotchMap<i32, i32> = HopscotchMap::with_capacity(100);
    let capacity = map.capacity();
    assert!(capacity >= 100);

    for i in 0..100 {
        map.insert((i, i));
    }
    map.clear();

    assert!(map.is_empty());
    assert_eq!(map.iter().count(), 0);
    assert_eq!(map.get(&0), None);
    assert_eq!(map.capacity(), capacity);
    assert!(map.insert((1, 1)));
}

